PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,full_name TEXT NOT NULL,phone_e164 TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,referral_code TEXT NOT NULL UNIQUE,referred_by_user_id TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','locked','closed')));
CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,principal_ugx INTEGER NOT NULL CHECK(principal_ugx>0),daily_figure_ugx INTEGER,duration_days INTEGER,terms_status TEXT NOT NULL DEFAULT 'unverified' CHECK(terms_status IN('unverified','approved','disabled')),image_path TEXT);
CREATE TABLE IF NOT EXISTS ledger_entries(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),entry_type TEXT NOT NULL,amount_ugx INTEGER NOT NULL CHECK(amount_ugx>0),direction TEXT NOT NULL CHECK(direction IN('credit','debit')),status TEXT NOT NULL CHECK(status IN('pending','posted','reversed','failed')),provider_reference TEXT UNIQUE,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,posted_at TEXT);
CREATE INDEX IF NOT EXISTS ledger_user_idx ON ledger_entries(user_id,created_at);
CREATE TABLE IF NOT EXISTS payment_requests(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),kind TEXT NOT NULL CHECK(kind IN('collection','disbursement')),amount_ugx INTEGER NOT NULL CHECK(amount_ugx>0),phone_e164 TEXT NOT NULL,provider TEXT NOT NULL DEFAULT 'marzpay',provider_reference TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'created' CHECK(status IN('created','pending','confirmed','failed','cancelled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
